using FallenForest.Core;using UnityEngine;namespace FallenForest.UI{public sealed class MainMenuController:MonoBehaviour{[SerializeField]private GameObject mainPanel,settingsPanel;public void Play()=>SceneFlow.PlayNewGame();public void Quit()=>SceneFlow.Quit();public void OpenSettings(){if(mainPanel!=null)mainPanel.SetActive(false);if(settingsPanel!=null)settingsPanel.SetActive(true);}public void CloseSettings(){if(settingsPanel!=null)settingsPanel.SetActive(false);if(mainPanel!=null)mainPanel.SetActive(true);}}}
